function sha256(value) {
  return crypto.createHash("sha256").update(value, "utf8").digest("hex");
}

function fail(message) {
  console.error("");
  console.error("Install stopped:");
  console.error(message);
  process.exit(1);
}

const panelFile = FILES[0];

if (!fs.existsSync(panelFile.target)) {
  fail(`Current Inspect Rides panel was not found: ${panelFile.target}`);
}

const currentPanel = fs.readFileSync(panelFile.target, "utf8");
const currentPanelHash = sha256(currentPanel);

if (
  currentPanelHash !== panelFile.expectedCurrentSha256 &&
  currentPanelHash !== sha256(panelFile.content)
) {
  fail(
    [
      "Your local inspect-rides-panel.tsx no longer matches the file you uploaded.",
      "Nothing was changed.",
      `Current SHA-256: ${currentPanelHash}`,
      `Expected SHA-256: ${panelFile.expectedCurrentSha256}`,
    ].join("\n"),
  );
}

const previousFiles = new Map();
const createdFiles = [];

try {
  for (const file of FILES) {
    fs.mkdirSync(path.dirname(file.target), { recursive: true });

    if (fs.existsSync(file.target)) {
      const previous = fs.readFileSync(file.target, "utf8");
      previousFiles.set(file.target, previous);

      const backupPath = path.join(path.dirname(file.target), file.backupName);
      fs.writeFileSync(backupPath, previous, "utf8");
    } else {
      createdFiles.push(file.target);
    }

    fs.writeFileSync(file.target, file.content, "utf8");
  }

  let typescript = null;

  try {
    typescript = require(path.join(ROOT, "node_modules", "typescript"));
  } catch {
    try {
      typescript = require("typescript");
    } catch {
      typescript = null;
    }
  }

  if (typescript) {
    for (const file of FILES) {
      const result = typescript.transpileModule(file.content, {
        compilerOptions: {
          target: typescript.ScriptTarget.ES2022,
          module: typescript.ModuleKind.ESNext,
          jsx: typescript.JsxEmit.ReactJSX,
        },
        fileName: file.target,
        reportDiagnostics: true,
      });

      const diagnostics = result.diagnostics || [];

      if (diagnostics.length > 0) {
        const message = diagnostics
          .map((diagnostic) =>
            typescript.flattenDiagnosticMessageText(
              diagnostic.messageText,
              "\n",
            ),
          )
          .join("\n");

        throw new Error(
          `TypeScript syntax validation failed for ${file.target}:\n${message}`,
        );
      }
    }
  }
} catch (error) {
  for (const [target, content] of previousFiles.entries()) {
    fs.writeFileSync(target, content, "utf8");
  }

  for (const target of createdFiles) {
    if (fs.existsSync(target)) {
      fs.unlinkSync(target);
    }
  }

  fail(
    [
      error instanceof Error ? error.message : String(error),
      "All edited files were restored.",
    ].join("\n"),
  );
}

